#ifndef CORE_CANVAS_H
#define CORE_CANVAS_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

#ifdef __cplusplus
extern "C" {
#endif

typedef struct {
  int w, h;
  uint16_t *px; /* px[y * w + x], RGB565 with the bytes swapped (display order) */
  /* Per row, the leftmost and rightmost x written since the last
   * canvas_clear_dirty; a row is clean when dirty_x0[y] > dirty_x1[y]. */
  int16_t *dirty_x0, *dirty_x1;
} Canvas;

/* Returns 0 on success, -1 if alloc returns NULL. */
int canvas_init(Canvas *c, int w, int h, void *(*alloc)(size_t));
void canvas_free(Canvas *c);

/* The display wants each pixel's high byte first, but the ESP32 stores a
 * uint16_t low byte first. Pixels are kept already swapped, so pushing the
 * canvas costs no per-pixel work. Only code that reads colour bits back (the
 * logo loader, the host dump) needs px_swap to get ordinary RGB565. */
uint16_t rgb565(uint8_t r, uint8_t g, uint8_t b);
uint16_t rgb565_from16(uint16_t r, uint16_t g, uint16_t b);
uint16_t px_swap(uint16_t v);

/* What the next push to the display must cover. A new canvas is dirty in full,
 * since the display still shows whatever was there before. */
void canvas_mark_dirty(Canvas *c, int x, int y, int w, int h);
bool canvas_dirty_row(const Canvas *c, int y, int *x0, int *x1); /* x1 inclusive */
void canvas_clear_dirty(Canvas *c);

/* All drawing is clipped to the canvas; any int coordinates are safe. */
void canvas_clear(Canvas *c, uint16_t color);
void canvas_point(Canvas *c, int x, int y, uint16_t color);
void canvas_line(Canvas *c, int x0, int y0, int x1, int y1, uint16_t color);
void canvas_fill_rect(Canvas *c, int x, int y, int w, int h, uint16_t color);
void canvas_fill_ellipse(Canvas *c, int x, int y, int w, int h, uint16_t color);
/* Copies the w*h rect at x,y into dst (row stride w), or writes it back from
 * src. Parts of the rect outside the canvas are skipped: their dst entries are
 * left alone on copy, and nothing is pasted for them. Lets a caller stamp
 * something over the canvas, push it, then put the hack's pixels back. */
void canvas_copy_rect(const Canvas *c, int x, int y, int w, int h, uint16_t *dst);
void canvas_paste_rect(Canvas *c, int x, int y, int w, int h, const uint16_t *src);
/* xy: x0,y0,x1,y1,... ; fewer than 3 points draws nothing. */
void canvas_fill_polygon(Canvas *c, const int *xy, int npoints, uint16_t color);

#ifdef __cplusplus
}
#endif

#endif
#ifndef CORE_PUSH_PLAN_H
#define CORE_PUSH_PLAN_H

#include "core/canvas.h"

#ifdef __cplusplus
extern "C" {
#endif

typedef struct {
  int y, x0, x1;       /* x1 inclusive */
  bool end_of_group;   /* last row of a batch: the display is flushed after it */
} PushRow;

typedef enum { PUSH_NONE, PUSH_ROWS, PUSH_ALL } PushKind;

/* Measured on the device (Pyro, 22 s per shape). M5GFX keeps a framebuffer for
 * this panel: each pushImage copies pixels into it, and endWrite sends the
 * bounding box of everything written since startWrite in one flush. So rows
 * pushed in one batch cost the box around all of them, and rows far apart are
 * cheaper in separate batches (two corner pixels: 11.7 ms together, 0.1 ms
 * apart). One batch costs a flush, plus the box it covers, plus a call and a
 * copy for each row written. A single full push costs PUSH_PIXEL_NS a pixel. */
#define PUSH_PIXEL_NS 143
#define PUSH_FLUSH_NS 17000
#define PUSH_FLUSH_ROW_NS 1600
#define PUSH_FLUSH_PIXEL_NS 54
#define PUSH_CALL_NS 1500
#define PUSH_COPY_PIXEL_NS 90

/* Turns the canvas's dirty spans into row pushes and marks every row clean.
 * `rows` has room for c->h entries. For PUSH_ROWS, `rows` holds *count entries
 * in increasing y, grouped into batches (the last row of each has
 * end_of_group); otherwise *count is 0. PUSH_ALL means the rows would cost at
 * least as much as pushing the whole canvas in one call. */
PushKind push_plan(Canvas *c, PushRow *rows, int *count);

typedef struct {
  void *ctx;
  void (*begin)(void *ctx);
  void (*row)(void *ctx, int y, int x0, int x1);
  void (*all)(void *ctx);
  void (*end)(void *ctx);
} PushSink;

/* Plans, then runs the plan through the sink: nothing for PUSH_NONE; for
 * PUSH_ROWS, begin, a row call per row, end, once per group; a single all for PUSH_ALL. Returns the
 * number of rows pushed (0, the row count, or c->h). */
int push_present(Canvas *c, PushRow *scratch, const PushSink *sink);

#ifdef __cplusplus
}
#endif

#endif
#include "core/push_plan.h"

typedef struct {
  int first_y, last_y, x0, x1;
  int64_t rows, pixels;
} Group;

static int64_t group_cost(const Group *g) {
  int64_t h = g->last_y - g->first_y + 1, w = g->x1 - g->x0 + 1;
  return PUSH_FLUSH_NS + h * PUSH_FLUSH_ROW_NS + w * h * PUSH_FLUSH_PIXEL_NS +
         g->rows * PUSH_CALL_NS + g->pixels * PUSH_COPY_PIXEL_NS;
}

static Group merge(const Group *a, const Group *b) {
  Group g = *a;
  g.last_y = b->last_y;
  if (b->x0 < g.x0) g.x0 = b->x0;
  if (b->x1 > g.x1) g.x1 = b->x1;
  g.rows += b->rows;
  g.pixels += b->pixels;
  return g;
}

PushKind push_plan(Canvas *c, PushRow *rows, int *count) {
  int n = 0;
  int64_t total_ns = 0;
  Group cur = {0};
  for (int y = 0; y < c->h; y++) {
    int x0, x1;
    if (!canvas_dirty_row(c, y, &x0, &x1)) continue;
    Group one = {y, y, x0, x1, 1, x1 - x0 + 1};
    if (n == 0) {
      cur = one;
    } else {
      Group merged = merge(&cur, &one);
      if (group_cost(&merged) <= group_cost(&cur) + group_cost(&one)) {
        cur = merged;
      } else {
        rows[n - 1].end_of_group = true;
        total_ns += group_cost(&cur);
        cur = one;
      }
    }
    rows[n++] = (PushRow){y, x0, x1, false};
  }
  canvas_clear_dirty(c);
  *count = 0;
  if (n == 0) return PUSH_NONE;
  rows[n - 1].end_of_group = true;
  total_ns += group_cost(&cur);
  if (total_ns >= (int64_t)c->w * c->h * PUSH_PIXEL_NS) return PUSH_ALL;
  *count = n;
  return PUSH_ROWS;
}

int push_present(Canvas *c, PushRow *scratch, const PushSink *sink) {
  int count;
  switch (push_plan(c, scratch, &count)) {
    case PUSH_NONE:
      return 0;
    case PUSH_ALL:
      sink->all(sink->ctx);
      return c->h;
    default:
      for (int i = 0; i < count; i++) {
        if (i == 0 || scratch[i - 1].end_of_group) sink->begin(sink->ctx);
        sink->row(sink->ctx, scratch[i].y, scratch[i].x0, scratch[i].x1);
        if (scratch[i].end_of_group) sink->end(sink->ctx);
      }
      return count;
  }
}

